  1 <= c <= 30 /\ rs + rz <= sz /\ 32 <= sz <= 65536 /\ 0 <= km /\ 262144 * km <= 3758096384
  /\ 0 <= w /\ 16 * w + sz <= cl_au (art_ca_pre c cl) /\ cl_au (art_ca_pre c cl) <= cl_mu (art_ca_pre c cl) /\ cl_mu (art_ca_pre c cl) <= 3758096384.
